chk_expense_account_movement_shape.value:
(
          `expense`.`source_account_id` IS NULL
          AND `expense`.`finance_transaction_id` IS NULL
        ) OR (
          BINARY `expense`.`payment_method` IN (
            BINARY 'cash', BINARY 'bank_transfer'
          )
          AND `expense`.`source_account_id` IS NOT NULL
          AND `expense`.`finance_transaction_id` IS NOT NULL
        )

chk_finance_account_bank_shape.value:
(
          BINARY `finance_account`.`account_type` = BINARY 'cash'
          AND `finance_account`.`bank_name` IS NULL
        ) OR (
          BINARY `finance_account`.`account_type` = BINARY 'bank'
          AND (
            `finance_account`.`bank_name` IS NULL
            OR (
              CHAR_LENGTH(`finance_account`.`bank_name`) BETWEEN 1 AND 191
              AND `finance_account`.`bank_name` = TRIM(`finance_account`.`bank_name`)
            )
          )
        )

chk_partnership_commission_rate.value:
(
          BINARY `partnership_commission`.`contribution_mode` = BINARY 'partner_only'
          AND `partnership_commission`.`share_rate` = 0.1000
        ) OR (
          BINARY `partnership_commission`.`contribution_mode` = BINARY 'user_one_side'
          AND `partnership_commission`.`share_rate` = 0.2500
        ) OR (
          BINARY `partnership_commission`.`contribution_mode` = BINARY 'user_both'
          AND `partnership_commission`.`share_rate` = 0.5000
        )

chk_work_task_priority.value:
BINARY `work_task`.`priority` IN (
        BINARY 'low', BINARY 'normal', BINARY 'high', BINARY 'urgent'
      )
